import {openMasterSync} from './master-sync.js';
import {readMasterFile,tableFromRows} from './master-import.js';
import {mount,shell} from './components.js';
const masters=['傷病名マスタ','銀行・支店マスタ','医療機関マスタ','診療科マスタ','医薬品マスタ'];
let chosen=0,tab='data',query='',tree=false,pending=true,threshold=90;
const configs={};
const config=()=>configs[chosen]||(configs[chosen]={definition:chosen===0?'ICD10_2013_階層定義.xlsx':'',sourceColumn:['ICD-10','銀行コード','機関コード','診療科コード','YJコード'][chosen]||'コード',nameColumn:['傷病名','銀行名','医療機関名','診療科名','医薬品名'][chosen]||'名称',threshold:90});
const schemas=[['レコードID','ICD-10','傷病名','特定疾病','特定部位'],['銀行コード','銀行名','支店コード','支店名'],['機関コード','医療機関名','カナ','都道府県'],['診療科コード','診療科名','カナ'],['YJコード','医薬品名','一般名']];
const uploads={};let importBook=null,importDraft=null;
const columns=()=>uploads[chosen]?.columns||schemas[chosen]||['コード','名称'];
const options=selected=>'<option value="">選択してください</option>'+columns().map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('');
let rows=[['CWF-1541','B370','口唇カンジダ症','B37.0','カンジダ性口内炎'],['CWF-1542','B370','舌カンジダ症','B37.0','カンジダ性口内炎'],['CWF-1543','B370','歯肉カンジダ症','B37.0','カンジダ性口内炎'],['CWF-1544','B370','カンジダ性口角びらん','B37.0','カンジダ性口内炎'],['CWF-1545','B370','カンジダ性口内炎','B37.0','カンジダ性口内炎'],['CWF-1548','B371','肺カンジダ症','B37.1','肺カンジダ症']];
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,id,primary=false)=>`<button class="button ${primary?'primary':''}" id="${id}">${text}</button>`;
function toast(t){$('toast').textContent=t;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,3500)}
function dialog(id,title,body,footer){return `<dialog id="${id}" class="wide-dialog"><div class="dialog-head"><h2>${title}</h2><button class="button link" data-close>閉じる</button></div><div class="dialog-body">${body}</div><div class="dialog-foot">${btn('キャンセル',id+'-cancel')}${footer}</div></dialog>`}
function render(){document.getElementById('sync-dialog')?.remove();mount(shell({active:'master',content:`<div class="toolbar"><h1 id="master-title">マスターデータ設定</h1><span class="demo">三期プロトタイプ · サンプルデータ</span></div><div class="master-layout"><aside class="master-list"><div class="list-head"><h2>マスタ一覧</h2><input id="master-search" type="text" aria-label="マスタ名で検索" placeholder="マスタ名で検索">${btn('＋ マスターデータ追加','add-master',true)}</div><div class="sources" id="sources">${masters.map((n,i)=>`<button data-master="${i}" class="${chosen===i?'selected':''}"><span>${esc(n)}</span><span>⋯</span></button>`).join('')}</div></aside><section class="master-main"><div class="master-head"><div class="toolbar"><h2>${esc(masters[chosen])}</h2><div class="sync-summary" id="sync-summary">${chosen===0?`<button id="open-sync-detail" class="button link">SFDC · 最終同期：10/21 03:00 · 更新 5件</button>${pending?'<span class="summary-divider">|</span><button id="open-pending" class="button link warning-link">失敗 1件</button>':''}`:'<span class="muted">手動更新</span>'}<button class="button" id="master-sync">データ同期</button></div></div><div class="master-controls"><div class="row master-actions">${btn('列設定','columns')}${btn('＋ 項目追加','add-row')}${btn('一括インポート','import',true)}<div class="inline-config"><label for="threshold">自動採用閾値</label><span class="threshold-help"><button id="threshold-info" class="info-button" type="button" aria-label="自動採用閾値の説明" aria-describedby="threshold-tooltip" aria-expanded="false">ⓘ</button><span id="threshold-tooltip" role="tooltip" class="tooltip-content">コードの完全一致結果がない場合、類似度がこの値以上の最上位候補を自動採用します。初期値90%、設定範囲75～100%。</span></span><input id="threshold" type="number" min="75" max="100" step="any" required value="${config().threshold}"><span>%</span></div></div><input id="table-search" type="text" aria-label="照合コード・各列で検索" placeholder="照合コード・各列で検索" value="${esc(query)}"></div></div><div class="tab-body" id="tab-body">${body('data')}</div><div class="footer-line master-footer">${btn('閉じる','close-master')}${btn('保存','save-settings')}${btn('再ベクトル化','retry-vector',true)}</div></section></div><div class="toast" id="toast" role="status" hidden></div>${dialogs()}`}));
document.querySelectorAll('.demo,.sample-note,.help,p.muted,p.notice').forEach(e=>e.remove());
document.querySelectorAll('.sidebar a:not([data-nav="api-settings"])').forEach(e=>e.remove());document.querySelectorAll('.sidebar .sub').forEach(e=>e.classList.toggle('active',e.textContent.includes('マスタ')));
$('close-master').onclick=()=>{document.querySelector('.master-main').hidden=true;document.querySelectorAll('[data-master]').forEach(e=>e.classList.remove('selected'))};$('threshold-info').onclick=()=>{const e=$('threshold-info');const open=e.getAttribute('aria-expanded')!=='true';e.setAttribute('aria-expanded',String(open));e.parentElement.classList.toggle('is-open',open)};$('threshold-info').onkeydown=e=>{if(e.key==='Escape'){$('threshold-info').setAttribute('aria-expanded','false');$('threshold-info').parentElement.classList.remove('is-open');$('threshold-info').blur()}};
$('master-sync').onclick=()=>openMasterSync(masters[chosen],()=>toast('同期設定を保存しました。'));
$('master-search').oninput=e=>document.querySelectorAll('[data-master]').forEach(b=>b.hidden=!b.textContent.includes(e.target.value));
document.querySelectorAll('[data-master]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.master);tab='data';query='';tree=false;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelector('.collapse').onclick=()=>document.querySelector('.layout').classList.toggle('collapsed');
for(const [id,d] of [['columns','columns-dialog'],['import','import-dialog'],['add-master','new-master-dialog'],['add-row','row-dialog']])$(id).onclick=()=>$(d).showModal();
if($('open-sync-detail'))$('open-sync-detail').onclick=()=>$('sync-detail-dialog').showModal();
if($('open-pending'))$('open-pending').onclick=()=>$('failure-dialog').showModal();
if($('open-review'))$('open-review').onclick=()=>$('failure-dialog').showModal();
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>$(d.id+'-cancel').onclick=()=>d.close());
$('definition-file').onchange=()=>{const f=$('definition-file').files[0];if(f)$('definition-current').textContent=f.name};
$('remove-definition').onclick=()=>{$('definition-current').textContent='未設定';$('definition-file').value=''};
$('save-columns').onclick=()=>{if($('definition-current').textContent!=='未設定'&&(!$('source-code-column').value||!$('source-name-column').value)){$('column-error').textContent='コード列と名称列を選択してください。';return}const f=$('definition-file').files[0];config().definition=$('definition-current').textContent==='未設定'?'':(f?f.name:config().definition);config().sourceColumn=$('source-code-column').value;config().nameColumn=$('source-name-column').value;render();toast('階層定義の設定を保存しました（デモ）。ファイルは解析・送信していません。')};
$('create-master').onclick=()=>{const n=$('new-master-name');if(!n.value.trim()){n.reportValidity();return}masters.push(n.value.trim());chosen=masters.length-1;tab='data';render();toast('マスタを追加しました（この画面内のデモ）')};
$('save-row').onclick=()=>{const n=$('row-name');if(!n.value.trim()){n.reportValidity();return}if(chosen===0){$('row-dialog').close();toast('追加データを更新失敗として受け付けました（デモ）');pending=true;tab='data';render();$('failure-dialog').showModal()}else{$('row-dialog').close();toast('項目を追加しました（デモ）')}};
$('import-file').onchange=async()=>{importBook=null;importDraft=null;$('sheet-field').hidden=true;try{const f=$('import-file').files[0];if(!f)return;importBook=await readMasterFile(f);$('import-sheet').innerHTML=importBook.sheets.map((t,i)=>`<option value="${i}">${esc(t.name)}</option>`).join('');$('sheet-field').hidden=importBook.sheets.length<2;$('import-error').textContent=''}catch(e){$('import-error').textContent=e.message}};
$('preview-import').onclick=async()=>{if(!importBook){$('import-error').textContent='読み取れるExcel / CSVを選択してください。';return}try{importDraft=tableFromRows(await importBook.sheets[Number($('import-sheet').value)].read());if(importDraft.rows.length>100000)throw Error('100,000件を超えています。更新しません。');$('import-dialog').close();$('preview-dialog').querySelector('.dialog-body').innerHTML=`<p>読込結果：${importDraft.rows.length}件</p><p>列：${importDraft.columns.map(esc).join(' ／ ')}</p>`;$('preview-dialog').showModal()}catch(e){$('import-error').textContent=e.message}};
$('apply-import').onclick=()=>{if(!importDraft)return;const append=document.querySelector('[name=import-mode]:checked').value==='append';if(append&&JSON.stringify(columns())!==JSON.stringify(importDraft.columns)){$('preview-dialog').close();$('import-dialog').showModal();$('import-error').textContent='追加更新は既存の列と一致する必要があります。列を変更する場合は上書更新を選択してください。';return}uploads[chosen]={columns:importDraft.columns,rows:append&&uploads[chosen]?[...uploads[chosen].rows,...importDraft.rows]:importDraft.rows};if(!columns().includes(config().sourceColumn))config().sourceColumn='';if(!columns().includes(config().nameColumn))config().nameColumn='';importDraft=null;render();toast('表と列の候補を更新しました。必要に応じて列設定を確認してください。')};
$('confirm-zero').onchange=e=>$('clear-now').disabled=!e.target.checked;$('clear-now').onclick=()=>{rows=[];tree=false;pending=false;$('zero-dialog').close();render();toast('本サンプルの顧客データをクリアしました。公式分類は保持します。')};
if($('table-search'))$('table-search').oninput=e=>{query=e.target.value;document.querySelectorAll('[data-record]').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(query.toLowerCase()))};
if($('view-table'))$('view-table').onclick=()=>{tree=false;render()};if($('view-tree'))$('view-tree').onclick=()=>{tree=true;render()};

if($('save-settings'))$('save-settings').onclick=()=>{if(!$('threshold').checkValidity()){$('threshold').reportValidity();return}config().threshold=Number($('threshold').value);toast('このマスタの設定を保存しました（この画面内のデモ）')};
if($('sync-now'))$('sync-now').onclick=()=>toast('API未接続です。下のサンプル結果で更新時の挙動を確認できます。');
if($('zero-sample'))$('zero-sample').onclick=()=>$('zero-dialog').showModal();if($('failed-sample'))$('failed-sample').onclick=()=>toast('今回のデータ取得は不完全です。更新せず、既存データを保持します。');
if($('retry-vector'))$('retry-vector').onclick=()=>toast('再ベクトル化の対象は失敗・変更分のみです（デモ）');
}
function body(view){if(view==='updates')return `<div class="toolbar"><span class="muted">SFDC · 毎日全量取得</span>${btn('今すぐ取得','sync-now')}</div><div class="notice">手動で更新したデータは、次回の上流同期で上書きされる場合があります。</div><h2>更新履歴（サンプル）</h2><table><thead><tr><th>更新元</th><th>結果</th><th>反映内容</th></tr></thead><tbody><tr><td>SFDC／日次</td><td class="status warning">一部更新失敗</td><td>正常分は反映済み。変更異常1件は旧版を保持。</td></tr><tr><td>手動／上書き</td><td class="status success">完了</td><td>未変更分の帰属・ベクトルを保持。</td></tr><tr><td>SFDC／日次</td><td class="status error">取得不完全</td><td>更新なし。既存データを保持。</td></tr><tr><td>手動／上書き</td><td class="status error">100,000件超過</td><td>全件失敗。既存データを保持。</td></tr></tbody></table><div class="actions">${btn('取得不完全の例','failed-sample')}${btn('全量0件の確認例','zero-sample')}</div>`;
if(uploads[chosen])return `<div class="table-wrap"><table><thead><tr>${columns().map(c=>`<th>${esc(c)}</th>`).join('')}<th>ベクトル化状態</th></tr></thead><tbody>${uploads[chosen].rows.slice(0,10).map(row=>`<tr data-record>${row.map(v=>`<td>${esc(v)}</td>`).join('')}<td>未処理</td></tr>`).join('')}</tbody></table></div><div class="pagination">${uploads[chosen].rows.length}件（先頭10件をプレビュー）</div>`;
return `<div class="table-wrap"><table><thead><tr><th>番号</th><th>レコードID</th><th>${chosen===0?'ICD-10':'コード'} <span class="tag">照会コード</span></th><th>${chosen===0?'傷病名':'名称'}</th>${!!config().definition?'<th id="hierarchy-column">上位階層（自動生成）</th>':''}<th>ベクトル化状態</th></tr></thead><tbody>${(chosen===0?rows:[['DEMO-1','0001','サンプル名称 A'],['DEMO-2','0002','サンプル名称 B']]).map((r,i)=>`<tr data-record><td>${i+1}</td><td>${r[0]}</td><td>${r[1]}</td><td>${esc(r[2])}</td>${!!config().definition?`<td class="hierarchy-path">${r[3]?`B37 カンジダ症`:'更新失敗'}</td>`:''}<td class="status success">完了</td></tr>`).join('')||'<tr><td colspan="6">データがありません。</td></tr>'}</tbody></table></div><div class="pagination">${chosen===0?rows.length:2} 件 <select aria-label="表示件数" style="width:120px"><option>10件ずつ</option></select><button class="button compact" disabled>‹</button><span>1</span><button class="button compact" disabled>›</button></div>`}
function dialogs(){return dialog('sync-detail-dialog','同期結果（サンプル）',`<div class="sync-detail"><p>同期完了：2026/10/21 03:00</p><p>更新元：SFDC（社内で作成・管理するマスタ）</p><p>更新方法：毎日全量取得・変更分のみ反映</p><table><tbody><tr><th>追加</th><td>2件</td></tr><tr><th>変更</th><td>2件</td></tr><tr><th>削除</th><td>1件</td></tr><tr><th>反映済み合計</th><td>5件</td></tr><tr><th>未反映・失敗</th><td>${pending?'1':'0'}件</td></tr></tbody></table><p class="muted">変更のない記録は更新件数に含みません。帰属判定に失敗した変更記録は、前回の正式記録を保持します。</p><p class="sample-note">表示はサンプルです。APIは未接続です。</p></div>`,'')+dialog('updates-dialog','更新履歴',body('updates'),'')+dialog('failure-dialog','更新失敗の詳細',`<p>正常な5件は反映済みです。失敗した変更記録は、前回の正式記録を保持します。</p><table><thead><tr><th>レコードID</th><th>取得データ</th><th>失敗理由</th></tr></thead><tbody><tr><td>CWF-1541</td><td>B370 ／ 肺カンジダ症</td><td>コードはB37.0、名称はB37.1に対応し、公式分類が不一致です。</td></tr></tbody></table><p class="muted">階層列を修正して保存後、既存の再ベクトル化を実行できます。元データ修正後の同期でも再処理します。</p>`,'')+dialog('columns-dialog','列設定',`<div class="field"><label for="definition-file">階層定義ファイル</label><div class="row"><span id="definition-current">${esc(config().definition||'未設定')}</span><button id="remove-definition" class="button link">解除</button></div><input type="file" id="definition-file" accept=".xlsx,.csv"><p class="sample-note">階層・code・名称の3列。ファイル選択はデモ表示のみで、解析・送信しません。</p></div><div class="mapping-columns"><div class="field"><label for="source-code-column">コード列</label><select id="source-code-column">${options(config().sourceColumn)}</select></div><span>＋</span><div class="field"><label for="source-name-column">名称列</label><select id="source-name-column">${options(config().nameColumn)}</select></div></div><p id="column-error" role="alert" class="status error"></p><p class="muted"></p><table><thead><tr><th>列名</th><th>照会コード</th></tr></thead><tbody>${columns().map((n,i)=>`<tr><td>${esc(n)}</td><td><input aria-label="${esc(n)}を照会コードに指定" type="checkbox" ${n===config().sourceColumn?'checked':''}></td></tr>`).join('')}</tbody></table>`,btn('保存','save-columns',true))+
dialog('import-dialog','一括インポート',`<div class="field"><label for="import-file">Excel / CSV</label><input type="file" id="import-file" accept=".xlsx,.csv"></div><div id="sheet-field" class="field" hidden><label for="import-sheet">シート</label><select id="import-sheet"></select></div><div class="row"><label><input type="radio" name="import-mode" value="append" checked>追加更新</label><label><input type="radio" name="import-mode" value="replace">上書更新</label></div><p class="notice">手動更新データは、次回の上流同期で上書きされる場合があります。</p><p class="sample-note">Excelの選択シートまたはUTF-8 CSVの先頭行を列名として読み込みます。ファイルはブラウザ内で処理し、送信しません。</p><p id="import-error" class="status error" role="alert"></p>`,btn('読込結果を確認','preview-import',true))+
dialog('preview-dialog','取り込み確認（サンプル）',`<p>コード変換 → 名称の完全一致による帰属 → 失敗理由の記録 → 変更分のベクトル化</p><table><tr><th>正常</th><td>5件・反映可能</td></tr><tr><th>変更・更新失敗</th><td>1件・前回の正式記録を保持</td></tr><tr><th>未変更</th><td>既存の帰属とベクトルを保持</td></tr></table><p class="notice">取り込み時に類似度検索・モデル判定は行いません。</p>`,btn('表示に反映','apply-import',true))+
dialog('zero-dialog','今回の全量0件を確認',`<p>取得が完了し、顧客データが0件でした。現在の顧客データをクリアしますか？</p><p class="notice warning">公式分類と既存OCR結果は保持します。承認は今回の更新のみに有効です。</p><label><input type="checkbox" id="confirm-zero">今回の顧客データのクリアを確認しました</label>`,`<button class="button primary" id="clear-now" disabled>今回のクリアを実行</button>`)+
dialog('new-master-dialog','マスターデータ追加',`<div class="field"><label for="new-master-name">マスタ名</label><input id="new-master-name" type="text" required></div>`,btn('追加','create-master',true))+
dialog('row-dialog','項目追加',`<div class="field"><label for="row-name">名称</label><input id="row-name" type="text" required></div><p class="muted">階層マスタは帰属を自動判定し、判定に失敗した新規記録は登録しません。</p>`,btn('追加','save-row',true))}
render();
